"""Complete six-cue and correct/wrong-cue endpoint reporting from saved tables."""
from .common import *
from .final_analysis import paired
from experiments.meta_objective_balance.statistics import summarize

def main():
 w=read('meta_wrong_cue_seed');metrics=[c for c in w if c not in ['seed','arm','dose','condition','phase']];summary=summarize(w,['arm','dose'],metrics,SEEDS);write_frame(OUT/'tables/meta_wrong_cue_summary.csv',summary);raw,ci=paired(w,['phase','dose'],metrics);write_frame(OUT/'tables/meta_wrong_cue_paired_seeds.csv',raw);write_frame(OUT/'tables/meta_wrong_cue_paired_intervals.csv',ci);s=read('meta_endpoint_cue_summary');s=s[s.phase.eq('F')&s.dose.eq(1920)];rows=[]
 for (a,c),g in s.groupby(['condition','cue']):
  q=g.set_index('metric');ce=q.loc['ce'];rows.append(dict(arm=a,cue=c,n=int(ce.n),mean_CE=ce['mean'],median_CE=ce['median'],CE_ci_low=ce.ci_low,CE_ci_high=ce.ci_high,mean_accuracy=q.loc['accuracy','mean'],mean_gap=q.loc['gap','mean'],median_gap=q.loc['gap','median']))
 f=pd.DataFrame(rows);write_frame(OUT/'tables/report_final_six_cues.csv',f);finalw=summary[summary.arm.isin(['U-F','P-F'])&summary.dose.eq(1920)];m=pd.read_csv(OUT/'tables/meta_mathematical_checks.csv.gz');cols=['double_operator_logit_error','double_operator_hidden_error','float32_logit_error','float32_logit_allowance','double_avg_error','double_both_error','double_Jensen_gap'];maxima=pd.DataFrame([dict(scope='78main histories;preflight separately verified',**{c:float(m[c].max()) for c in cols})]);write_frame(OUT/'tables/mathematical_validation_maxima.csv',maxima)
 text='## Exact final six-cue and wrong-cue results\n\nAll six seeds at final FOMAML+1920, after target update330:\n\n'+f.to_markdown(index=False,floatfmt='.6g')+'\n\nComplete mean/median bootstrap intervals at every fixed phase/dose are in `meta_endpoint_cue_summary.csv`. Wrong-cue/correct-cue CE summaries below use independent20-update conflict diagnostic copies from each meta-initialization, not target330 weights;12 tasks are averaged within each seed first.\n\n'+finalw[['arm','metric','n','mean','median','ci_low','ci_high']].to_markdown(index=False,floatfmt='.6g')+'\n\nFull per-seed correct/wrong results and paired P−U mean/median intervals for all phases/doses are in `meta_wrong_cue_seed.csv` and `meta_wrong_cue_paired_intervals.csv`. No cue-performance threshold or new training was introduced for this export.\n\nNumerical affine validation maxima across78 main histories (the12 preflight histories are also separately verified):\n\n'+maxima.to_markdown(index=False,floatfmt='.6g')+'\n\nThe float32 allowance is a conservative propagated per-cell arithmetic bound, not an observed error or fitted tolerance. Every cell meets its own bound. Double identities and native errors are checked separately.\n\n'
 p=OUT/'REPORT.md';p.write_text(p.read_text().replace('## Figures\n',text+'## Figures\n'));dump(OUT/'audit/numeric_supplements_complete.json',dict(passed=True,all_six_cue_endpoint_means_medians_accuracy=True,all_correct_wrong_metrics=True,whole_seed_pairs=6,bootstrap=10000,all_fixed_checkpoints=True,optimizer_updates=0));append('## Numerical reporting completion\nAdded explicit final sixcue means/medians/accuracy/gaps and correct/wrongcue cohort/paired intervals at all fixed checkpoints. Independent arithmetic maxima report double identities separately from conservative nativefloat32 bounds. All exports read saved records only; no new evaluation/optimization/threshold changes.')
if __name__=='__main__':main()
